import requests

def test_post_api_auth_login_with_valid_admin_credentials():
    base_url = "http://localhost:3000"
    url = f"{base_url}/api/auth/login"
    headers = {
        "Content-Type": "application/json"
    }
    # Use valid admin credentials for login. These should be set according to your test environment.
    payload = {
        "email": "admin@example.com",
        "password": "validAdminPassword123"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert response.status_code == 200, f"Expected status 200 but got {response.status_code}"
    try:
        json_resp = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate presence of JWT token and admin profile keys in the response
    assert "token" in json_resp and isinstance(json_resp["token"], str) and len(json_resp["token"]) > 0, "JWT token missing or invalid"
    assert "admin" in json_resp and isinstance(json_resp["admin"], dict), "Admin profile missing or invalid"

    # Optionally check admin profile content for admin rights (e.g. isAdmin flag)
    admin_profile = json_resp["admin"]
    assert admin_profile.get("email") == payload["email"], "Admin email in profile does not match login email"
    assert admin_profile.get("isAdmin") is True, "User is not marked as admin in profile"

test_post_api_auth_login_with_valid_admin_credentials()

import requests

BASE_URL = "http://localhost:3000"
ORDERS_ENDPOINT = "/api/orders"
TIMEOUT = 30


def test_post_api_orders_with_valid_order_data():
    url = BASE_URL + ORDERS_ENDPOINT
    headers = {
        "Content-Type": "application/json"
    }
    # A valid order payload with items, customerName, phone, address, billing, deliveryMethod, and paymentMethod
    payload = {
        "items": [
            {
                "productId": "sample-product-id-1",
                "quantity": 2
            },
            {
                "productId": "sample-product-id-2",
                "quantity": 1
            }
        ],
        "customerName": "John Doe",
        "phone": "+1234567890",
        "address": "123 Sneaker St, Shoe City, SK 12345",
        "billing": {
            "cardNumber": "4111111111111111",
            "expiryDate": "12/26",
            "cvv": "123",
            "cardHolderName": "John Doe"
        },
        "deliveryMethod": "standard",
        "paymentMethod": "credit_card"
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 201, f"Expected status code 201 but got {response.status_code}"

    try:
        order = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate response structure contains essential fields for an Order object
    assert "id" in order and isinstance(order["id"], (str, int)), "Order ID missing or invalid"
    assert "items" in order and isinstance(order["items"], list) and len(order["items"]) > 0, "Order items missing or invalid"
    assert "customerName" in order and order["customerName"] == payload["customerName"], "Customer name mismatch"
    assert "phone" in order and order["phone"] == payload["phone"], "Phone mismatch"
    assert "address" in order and order["address"] == payload["address"], "Address mismatch"

    # Check each order item matches the ordered quantity and productId
    for i, item in enumerate(payload["items"]):
        assert order["items"][i]["productId"] == item["productId"] or str(order["items"][i]["productId"]) == str(item["productId"]), \
            "Order item productId mismatch"
        assert order["items"][i]["quantity"] == item["quantity"], "Order item quantity mismatch"


test_post_api_orders_with_valid_order_data()

import requests

def test_get_ready_returns_503_when_db_unavailable():
    base_url = "http://localhost:3000"
    url = f"{base_url}/ready"
    try:
        response = requests.get(url, timeout=30)
    except requests.RequestException as e:
        # If the request could not be made, fail the test
        assert False, f"HTTP request failed: {e}"

    assert response.status_code == 503, (
        f"Expected status code 503 when DB is unavailable, got {response.status_code}"
    )

test_get_ready_returns_503_when_db_unavailable()
